// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _val) public {
        vm.assume(_val != 0 && _val != 1 ether);
        // Initialize the contract
        c.Initialized();
        // Record MinSum before calling SetMinSum
        uint before = c.MinSum();
        // Try to call SetMinSum (should revert in reference, succeed in mutant)
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", _val));
        // After the call, MinSum must equal the original value (reference: reverts so unchanged; mutant: changes but we assert it should not)
        assertTrue(c.MinSum() == before);
    }
}

